const D = { scale:1, density:.3, moths:6, hue:42, energy:.6, speed:1, x:.5, y:.44, flicker:.25, seed:0, style:'sodium', act:'still' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const st = P.style;
const hue = ((P.hue%360)+360)%360;
const cx = P.x*width, headY = P.y*height;
const sc = P.scale;
const nMoth = Math.max(0, Math.min(14, Math.round(P.moths)));

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;

if (S.lt == null || K.t < S.lt) S.lt = K.t;
let dt = K.t - S.lt; S.lt = K.t;
if (dt < 0 || dt > 0.2) dt = 1/60;

function pal(){
  if (st==='mercury')   return { post:[210,20,26], lampH:150, lampS:35, glow:[160,60,100], cone:[165,45,100], pool:[170,50,95], rain:[195,25,80], moth:[190,10,85], schem:false };
  if (st==='noir')      return { post:[hue,6,14], lampH:44, lampS:20, glow:[46,30,100], cone:[44,18,100], pool:[44,14,92], rain:[hue,4,78], moth:[hue,3,70], schem:false, hard:true };
  if (st==='schematic') return { post:[200,50,20], lampH:195, lampS:40, glow:[195,70,95], cone:[195,60,90], pool:[195,50,85], rain:[195,55,80], moth:[50,80,95], schem:true };
  if (st==='thermal')   return { post:[250,55,18], lampH:52, lampS:90, glow:[52,95,100], cone:[30,90,95], pool:[15,85,80], rain:[210,70,60], moth:[60,95,100], schem:false, therm:true };
  // sodium (default): warm sodium-vapor pool
  return { post:[hue,14,20], lampH:hue, lampS:40, glow:[hue,55,100], cone:[hue,48,100], pool:[(hue+6)%360,42,96], rain:[hue,12,82], moth:[hue,8,80] };
}
const C = pal();

const postW = u*sc*0.02;
const groundY = height*0.96;
const coneLen = groundY - headY;
const coneHalf = u*sc*0.24;

// ---- cached post + fixture + faint ground pool base ----
const bkey = width+'x'+height+':'+st+':'+P.seed+':'+sc.toFixed(2)+':'+P.x.toFixed(2)+':'+P.y.toFixed(2);
if (!S.bg || S.bgKey !== bkey){
  S.bgKey = bkey;
  const g = (S.bg && S.bg.width===width && S.bg.height===height) ? S.bg : (S.bg = createGraphics(width,height));
  g.colorMode(HSB,360,100,100,100); g.clear(); g.push();
  g.noStroke();
  if (C.schem){
    // blueprint: line-only lamp elevation + cone rays + photometric arcs
    g.stroke(C.cone[0],C.cone[1],C.cone[2],85); g.strokeWeight(Math.max(1,u*0.0015)); g.noFill();
    g.line(cx, headY, cx, groundY);                 // post
    g.line(cx, headY, cx+u*sc*0.06, headY);         // arm
    const hx = cx+u*sc*0.06;
    g.rect(hx-postW*1.4, headY-postW, postW*2.8, postW*2.2); // lamp box
    g.line(hx, headY+postW, hx-coneHalf, groundY);  // cone edges
    g.line(hx, headY+postW, hx+coneHalf, groundY);
    for (let r=1;r<=4;r++){ g.arc(hx, headY+postW, coneHalf*2*r/4*2, coneHalf*2*r/4*2, Math.PI*0.15, Math.PI*0.85); }
    for (let k=0;k<7;k++){ const t=k/6; g.point(cx, headY+t*coneLen); } // dimension ticks
    g.pop();
  } else {
    // ground pool of warm light (radial-ish, few bands)
    const px = cx+u*sc*0.06;
    g.push(); g.blendMode(C.hard?BLEND:BLEND);
    for (let r=9;r>0;r--){ const t=r/9; g.fill(C.pool[0],C.pool[1]*0.5,C.pool[2], (C.hard?5:4)); g.ellipse(px, groundY-u*sc*0.01, coneHalf*2*t*1.15, coneHalf*0.7*t); }
    g.pop();
    // cast post shadow across the pool
    g.fill(C.post[0],C.post[1],C.post[2]*0.4,55);
    g.quad(px-postW*0.4, groundY, px+postW*0.4, groundY, px+coneHalf*0.5, groundY-u*sc*0.004, px+coneHalf*0.5+postW, groundY-u*sc*0.004);
    // the post
    g.fill(C.post[0],C.post[1],C.post[2],100);
    g.rect(cx-postW/2, headY, postW, groundY-headY, postW*0.4);
    g.fill(C.post[0],C.post[1]*0.6,C.post[2]*1.5,60); g.rect(cx-postW/2, headY, postW*0.35, groundY-headY); // rim light
    // base plinth
    g.fill(C.post[0],C.post[1],C.post[2]*0.8,100); g.rect(cx-postW*1.6, groundY-u*sc*0.02, postW*3.2, u*sc*0.02, postW*0.3);
    // arm + lamp head fixture
    g.stroke(C.post[0],C.post[1],C.post[2],100); g.strokeWeight(postW*0.8); g.noFill();
    g.line(cx, headY, cx+u*sc*0.06, headY); g.noStroke();
    const hx = cx+u*sc*0.06;
    g.fill(C.post[0],C.post[1],C.post[2]*1.3,100);
    g.beginShape(); g.vertex(hx-postW*1.5, headY-postW*0.5); g.vertex(hx+postW*1.5, headY-postW*0.5); g.vertex(hx+postW*0.9, headY+postW*1.8); g.vertex(hx-postW*0.9, headY+postW*1.8); g.endShape(CLOSE);
    // glass
    g.fill(C.glow?C.glow[0]:hue, 30, 40, 100); g.ellipse(hx, headY+postW*0.5, postW*2.2, postW*2.6);
    g.pop();
  }
  S.headX = C.schem? cx+u*sc*0.06 : cx+u*sc*0.06;
}
image(S.bg, 0, 0);
const hx = S.headX;

// ---- flicker (rare, seeded, real-time) ----
S.flk = (S.flk==null)?1:S.flk;
// occasional dips: probability scales with P.flicker
if (fr(Math.floor(K.t*8)) < P.flicker*0.12){ S.flkTarget = 0.35 + fr(Math.floor(K.t*8)+3)*0.4; }
else S.flkTarget = 1;
S.flk += (S.flkTarget - S.flk) * Math.min(1, dt*22);
const lampOn = S.flk * (0.85 + S.tre*0.5);

// ---- act shaping ----
let rainMul=1, mothAgi=1;
if (P.act==='storm'){ rainMul = 0.6 + K.intensity*1.8; mothAgi=0.5; }
else if (P.act==='swarm'){ mothAgi = 1.8; rainMul=0.5; }
else { rainMul = 0.8 + Math.sin(K.t*0.3)*0.2; } // still: slow drift

// ---- light cone (glow) ----
push();
if (!C.schem){
  blendMode(C.therm?SCREEN:ADD);
  noStroke();
  const layers = 5;
  for (let l=0;l<layers;l++){ const t=l/(layers-1);
    fill(C.cone[0], C.cone[1]*(0.8-t*0.5), C.cone[2], (C.hard?11:8)*lampOn*(1-t*0.4));
    const hw = coneHalf*(0.35+t*0.65);
    beginShape();
    vertex(hx-postW*1.2, headY+postW);
    vertex(hx+postW*1.2, headY+postW);
    vertex(hx+hw, groundY);
    vertex(hx-hw, groundY);
    endShape(CLOSE);
  }
  // hot core near the bulb
  fill(C.glow[0],C.glow[1]*0.5,C.glow[2], 40*lampOn);
  ellipse(hx, headY+postW*0.6, postW*4*lampOn, postW*4*lampOn);
}
pop();

// ---- rain streaks in/around the cone (real-time fall) ----
if (P.density>0.02 && !C.schem){
  push();
  const nR = Math.round(P.density*120*rainMul);
  stroke(C.rain[0],C.rain[1],C.rain[2], 45+S.rms*30);
  strokeWeight(Math.max(1,u*0.0012));
  const wind = Math.sin(K.t*0.5)*0.18 + (P.act==='storm'?0.25:0);
  for (let i=0;i<nR;i++){
    const seedX = fr(i*1.7);
    const speed = (0.5+fr(i*2.3)*0.6);
    // real-time vertical scroll, wraps — never re-phases
    const yy = ((fr(i*3.1) + K.t*speed*0.5) % 1);
    const rx = hx + (seedX-0.5)*coneHalf*2.1 + yy*coneLen*wind;
    const ry = headY + yy*coneLen;
    const len = u*sc*0.03*(0.6+speed);
    const lit = ry>headY? lampOn:0.4;
    stroke(C.rain[0],C.rain[1],C.rain[2], (30+40*lit)*(0.6+P.density*0.6));
    line(rx, ry, rx+wind*len, ry+len);
  }
  pop();
}

// ---- moths orbiting the lamp (seeded erratic, real-time) ----
push();
for (let i=0;i<nMoth;i++){
  const f1 = 0.6+fr(i*5+1)*1.4, f2 = 0.5+fr(i*5+2)*1.6;
  const ax = coneHalf*(0.25+fr(i*5+3)*0.5), ay = coneHalf*(0.18+fr(i*5+4)*0.35);
  const ph1 = fr(i*5+5)*6.28, ph2 = fr(i*5+6)*6.28;
  const tt = K.t*mothAgi*(0.8+P.energy*0.6);
  const jit = Math.sin(tt*7+i)*coneHalf*0.04*mothAgi;
  const mx = hx + Math.cos(tt*f1+ph1)*ax + jit;
  const my = (headY+postW*0.5) + Math.sin(tt*f2+ph2)*ay + Math.cos(tt*1.7+i)*coneHalf*0.05;
  const flap = 0.5+0.5*Math.sin(tt*14+i*2);
  const sz = u*sc*0.012*(0.7+fr(i*5+7)*0.6);
  noStroke();
  fill(C.moth[0],C.moth[1],C.moth[2], 85*lampOn);
  // two wing triangles flapping
  push(); translate(mx,my);
  const wa = 0.4+flap*0.9;
  triangle(0,0, -sz*Math.cos(wa)*1.6, -sz*Math.sin(wa)*1.2, -sz*1.5, sz*0.5);
  triangle(0,0,  sz*Math.cos(wa)*1.6, -sz*Math.sin(wa)*1.2,  sz*1.5, sz*0.5);
  fill(C.post[0],C.post[1],C.post[2]*1.2, 90*lampOn); ellipse(0,0,sz*0.5,sz*1.1);
  pop();
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
